import { readFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { logger } from './logger.js'

const CONFIG_DIR = new URL('../config/', import.meta.url).pathname

function readJson(name) {
  const path = join(CONFIG_DIR, name)
  return existsSync(path) ? JSON.parse(readFileSync(path, 'utf8')) : {}
}

function merge(base, override) {
  const out = { ...base }
  for (const [k, v] of Object.entries(override)) {
    out[k] = v && typeof v === 'object' && !Array.isArray(v) ? merge(base[k] ?? {}, v) : v
  }
  return out
}

// Environment variable -> config path. Values are parsed as integers when the default is a number.
const ENV_OVERRIDES = {
  PORT: ['port'],
  DB_HOST: ['db', 'host'],
  SHOPAPI_POOL_MAX: ['db', 'poolMax'],
  CACHE_TTL_SECONDS: ['cache', 'ttlSeconds'],
  LOG_LEVEL: ['logLevel'],
}

// Deprecated unprefixed names, kept working during the SHOPAPI_ migration. Deprecated
// name -> canonical name. Canonical wins if both are set.
const DEPRECATED_ALIASES = {
  POOL_MAX: 'SHOPAPI_POOL_MAX',
}

const warnedAliases = new Set()

export function loadConfig(env = process.env) {
  let config = merge(readJson('default.json'), readJson(`${env.NODE_ENV ?? 'development'}.json`))

  const resolvedEnv = { ...env }
  for (const [deprecated, canonical] of Object.entries(DEPRECATED_ALIASES)) {
    if (env[deprecated] === undefined) continue
    if (!warnedAliases.has(deprecated)) {
      warnedAliases.add(deprecated)
      logger.warn(`${deprecated} is deprecated, use ${canonical} instead`, { deprecated, canonical })
    }
    if (resolvedEnv[canonical] === undefined) resolvedEnv[canonical] = env[deprecated]
  }

  for (const [name, path] of Object.entries(ENV_OVERRIDES)) {
    if (resolvedEnv[name] === undefined) continue
    let target = config
    for (const key of path.slice(0, -1)) target = target[key]
    const last = path[path.length - 1]
    target[last] = typeof target[last] === 'number' ? Number.parseInt(resolvedEnv[name], 10) : resolvedEnv[name]
  }
  return config
}

