import { test } from 'node:test'
import assert from 'node:assert/strict'
import { loadConfig } from '../src/config.js'
import { logger } from '../src/logger.js'

test('defaults', () => {
  assert.equal(loadConfig({}).db.poolMax, 10)
})

test('production file overrides the host', () => {
  assert.equal(loadConfig({ NODE_ENV: 'production' }).db.host, 'db.internal')
})

test('PORT env var overrides the port', () => {
  assert.equal(loadConfig({ PORT: '8080' }).port, 8080)
})

test('SHOPAPI_POOL_MAX overrides the pool size', () => {
  assert.equal(loadConfig({ SHOPAPI_POOL_MAX: '40' }).db.poolMax, 40)
})

test('POOL_MAX still works as a deprecated alias', () => {
  assert.equal(loadConfig({ POOL_MAX: '40' }).db.poolMax, 40)
})

test('SHOPAPI_POOL_MAX wins when both are set', () => {
  assert.equal(loadConfig({ POOL_MAX: '5', SHOPAPI_POOL_MAX: '40' }).db.poolMax, 40)
})

test('POOL_MAX logs a deprecation warning exactly once per process', () => {
  const original = logger.warn
  const calls = []
  logger.warn = (msg, fields) => calls.push({ msg, fields })
  try {
    loadConfig({ POOL_MAX: '40' })
    loadConfig({ POOL_MAX: '40' })
  } finally {
    logger.warn = original
  }
  assert.equal(calls.length, 1)
  assert.match(calls[0].msg, /POOL_MAX is deprecated/)
})

